//! Compound File Binary reader tests against tests/fixtures/cfb (generated by
//! tests/gen/ms.py from MS-CFB; 7-Zip 26.04 lists and extracts the same
//! contents per tests/gen/ms_oracle.sh).

mod ms_common;
use ms_common::{crc, cut_points, expect, fixture, mutations};
use sediment_engine::cfb_read::{
    CfbArchive, CfbEntryKind, CfbError, CfbLimits, MsiNames, decode_msi_name, filetime_to_unix,
};
use sediment_engine::extract_plan::EntryKind;

fn lim() -> CfbLimits {
    CfbLimits::default()
}

fn check(name: &str, limits: CfbLimits) {
    let bytes = fixture("cfb", name);
    let cfb = CfbArchive::parse(&bytes, limits).unwrap();
    let exp = expect("cfb", name);
    assert_eq!(cfb.entries().len(), exp.len(), "{name}: entry count");
    for e in &exp {
        let i = cfb.find(&e.path).unwrap_or_else(|| panic!("{name}: missing {}", e.path));
        let ent = &cfb.entries()[i];
        if e.dir {
            assert_eq!(ent.kind, CfbEntryKind::Storage, "{name}: {}", e.path);
            assert_eq!(cfb.read(i), Err(CfbError::NotAStream));
        } else {
            assert_eq!(ent.kind, CfbEntryKind::Stream, "{name}: {}", e.path);
            assert_eq!(ent.size, e.size, "{name}: {} size", e.path);
            let d = cfb.read(i).unwrap_or_else(|err| panic!("{name}: {}: {err:?}", e.path));
            assert_eq!(Some(crc(&d)), e.crc, "{name}: {} crc", e.path);
        }
    }
}

#[test]
fn version3_document() {
    check("doc.cfb", lim());
    let bytes = fixture("cfb", "doc.cfb");
    let cfb = CfbArchive::parse(&bytes, lim()).unwrap();
    assert_eq!(cfb.major_version, 3);
    assert_eq!(cfb.sector_size, 512);
    assert_eq!(cfb.mini_cutoff, 4096);
    let pool = &cfb.entries()[cfb.find("ObjectPool").unwrap()];
    assert_eq!(pool.mtime_unix(), Some(1_705_526_400));
    let summary = &cfb.entries()[cfb.find("[5]SummaryInformation").unwrap()];
    assert_eq!(summary.name_utf16[0], 5);
    // parents precede children; siblings come out in CFB order (length, then
    // case-insensitive)
    let paths: Vec<&str> = cfb.entries().iter().map(|e| e.path.as_str()).collect();
    let pos = |p: &str| paths.iter().position(|x| *x == p).unwrap();
    assert!(pos("ObjectPool") < pos("ObjectPool/_1234"));
    assert!(pos("ObjectPool/_1234") < pos("ObjectPool/_1234/CONTENTS"));
    assert!(pos("Data") < pos("Small") && pos("Small") < pos("1Table"));
    let pe = cfb.planned_entries();
    assert_eq!(pe[pos("ObjectPool")].kind, EntryKind::Dir);
    assert_eq!(pe[pos("WordDocument")].size, 9000);
}

#[test]
fn version4_document() {
    check("v4.cfb", lim());
    let bytes = fixture("cfb", "v4.cfb");
    let cfb = CfbArchive::parse(&bytes, lim()).unwrap();
    assert_eq!(cfb.major_version, 4);
    assert_eq!(cfb.sector_size, 4096);
}

#[test]
fn difat_sector_chain() {
    // 110 FAT sectors: the 110th is listed in a DIFAT sector
    check("difat.cfb", lim());
    let bytes = fixture("cfb", "difat.cfb");
    assert_eq!(u32::from_le_bytes(bytes[0x2C..0x30].try_into().unwrap()), 110);
    assert_eq!(u32::from_le_bytes(bytes[0x48..0x4C].try_into().unwrap()), 1);
}

#[test]
fn msi_names() {
    check("names.msi", lim());
    let bytes = fixture("cfb", "names.msi");
    let raw = CfbArchive::parse(&bytes, CfbLimits { msi_names: MsiNames::Never, ..lim() }).unwrap();
    assert!(raw.find("!_Tables").is_none());
    assert!(raw.entries().iter().any(|e| e.path.starts_with('\u{4840}')));
    assert_eq!(decode_msi_name(&[0x4840, 0x3800 + 63 + (36 << 6)]), "!_a".encode_utf16().collect::<Vec<_>>());
    assert_eq!(decode_msi_name(&[0x4800 + 10, b'x' as u16]), "Ax".encode_utf16().collect::<Vec<_>>());
    // a plain document is left alone under Auto
    let doc = fixture("cfb", "doc.cfb");
    assert!(CfbArchive::parse(&doc, lim()).unwrap().find("WordDocument").is_some());
}

#[test]
fn filetime_conversion() {
    assert_eq!(filetime_to_unix(0), None);
    assert_eq!(filetime_to_unix(116_444_736_000_000_000), Some(0));
}

#[test]
fn bad_headers() {
    assert_eq!(CfbArchive::parse(b"", lim()).err(), Some(CfbError::Truncated));
    assert_eq!(CfbArchive::parse(&[0u8; 600], lim()).err(), Some(CfbError::InvalidSignature));
    let good = fixture("cfb", "doc.cfb");
    for (at, val, err) in [
        (0x1A, 5u8, CfbError::InvalidHeader), // major version
        (0x1C, 0, CfbError::InvalidHeader),   // byte order
        (0x1E, 12, CfbError::InvalidHeader),  // v3 with 4096-byte sectors
        (0x20, 7, CfbError::InvalidHeader),   // mini sector shift
        (0x2F, 0x7F, CfbError::InvalidHeader), // huge FAT sector count
    ] {
        let mut b = good.clone();
        b[at] = val;
        assert_eq!(CfbArchive::parse(&b, lim()).err(), Some(err), "byte {at:#x}");
    }
    assert_eq!(CfbArchive::parse(&good[..511], lim()).err(), Some(CfbError::Truncated));
}

fn dir_entry_offset(bytes: &[u8], id: usize) -> usize {
    // fixtures keep the directory in one run of sectors (v3)
    let first = u32::from_le_bytes(bytes[0x30..0x34].try_into().unwrap()) as usize;
    (first + 1) * 512 + id * 128
}

#[test]
fn directory_cycle_is_rejected() {
    let mut bytes = fixture("cfb", "doc.cfb");
    let root = dir_entry_offset(&bytes, 0);
    let child = u32::from_le_bytes(bytes[root + 76..root + 80].try_into().unwrap()) as usize;
    let c = dir_entry_offset(&bytes, child);
    bytes[c + 68..c + 72].copy_from_slice(&(child as u32).to_le_bytes()); // left -> itself
    assert_eq!(CfbArchive::parse(&bytes, lim()).err(), Some(CfbError::InvalidDirectory));
    // link to an out-of-range entry
    let mut bytes = fixture("cfb", "doc.cfb");
    bytes[c + 72..c + 76].copy_from_slice(&5000u32.to_le_bytes());
    assert_eq!(CfbArchive::parse(&bytes, lim()).err(), Some(CfbError::InvalidDirectory));
    // root of wrong type
    let mut bytes = fixture("cfb", "doc.cfb");
    bytes[root + 66] = 1;
    assert_eq!(CfbArchive::parse(&bytes, lim()).err(), Some(CfbError::InvalidDirectory));
}

#[test]
fn fat_loop_is_rejected() {
    let bytes = fixture("cfb", "doc.cfb");
    let cfb = CfbArchive::parse(&bytes, lim()).unwrap();
    let i = cfb.find("WordDocument").unwrap();
    let id = cfb.entries()[i].dir_id as usize;
    let e = dir_entry_offset(&bytes, id);
    let start = u32::from_le_bytes(bytes[e + 116..e + 120].try_into().unwrap());
    // FAT sector is the first in the header DIFAT list
    let fat_sec = u32::from_le_bytes(bytes[0x4C..0x50].try_into().unwrap()) as usize;
    let mut bad = bytes.clone();
    let slot = (fat_sec + 1) * 512 + 4 * (start as usize + 1);
    bad[slot..slot + 4].copy_from_slice(&start.to_le_bytes()); // 2nd sector points back
    let cfb = CfbArchive::parse(&bad, lim()).unwrap();
    assert_eq!(cfb.read(i), Err(CfbError::InvalidChain));
    // chain ends early
    let mut bad = bytes.clone();
    bad[slot..slot + 4].copy_from_slice(&0xFFFF_FFFEu32.to_le_bytes());
    let cfb = CfbArchive::parse(&bad, lim()).unwrap();
    assert_eq!(cfb.read(i), Err(CfbError::InvalidChain));
}

#[test]
fn limits() {
    let bytes = fixture("cfb", "doc.cfb");
    let cfb = CfbArchive::parse(&bytes, CfbLimits { max_stream_size: 100, ..lim() }).unwrap();
    assert_eq!(cfb.read(cfb.find("WordDocument").unwrap()), Err(CfbError::LimitExceeded));
    assert_eq!(cfb.read(9999), Err(CfbError::OutOfRange));
    assert_eq!(CfbArchive::parse(&bytes, CfbLimits { max_entries: 3, ..lim() }).err(), Some(CfbError::LimitExceeded));
}

#[test]
fn truncation_never_panics() {
    for name in ["doc.cfb", "v4.cfb", "names.msi"] {
        let bytes = fixture("cfb", name);
        for cut in cut_points(bytes.len()) {
            if let Ok(cfb) = CfbArchive::parse(&bytes[..cut], lim()) {
                for i in 0..cfb.entries().len() {
                    let _ = cfb.read(i);
                }
            }
        }
    }
}

#[test]
fn mutations_never_panic() {
    for (k, name) in ["doc.cfb", "v4.cfb", "names.msi", "difat.cfb"].iter().enumerate() {
        let bytes = fixture("cfb", name);
        for m in mutations(&bytes, 200, 0xCFB0 + k as u64) {
            if let Ok(cfb) = CfbArchive::parse(&m, lim()) {
                for i in 0..cfb.entries().len() {
                    let _ = cfb.read(i);
                }
                let _ = cfb.planned_entries();
            }
        }
        // mutations concentrated in the header and directory
        let head = bytes.len().min(4096);
        for m in mutations(&bytes[..head], 200, 0xD1 + k as u64) {
            let mut b = bytes.clone();
            b[..m.len()].copy_from_slice(&m);
            if let Ok(cfb) = CfbArchive::parse(&b, lim()) {
                for i in 0..cfb.entries().len() {
                    let _ = cfb.read(i);
                }
            }
        }
    }
}
